insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',1,'Língua Portuguesa',null,'Em cada texto a seguir, retirado do jornal O Globo, ocorrem processos de dar precisão e segurança ao que se transmite; a opção em que NÃO há marcas dessa estratégia é:','{"A": "“O Surfe: historiador revela como o ritual religioso dos antigos polinésios virou esporte nos EUA”;", "B": "“O ensino atual de literatura está afastando os jovens dos livros, alerta o influente crítico francês Tzvetan Todorov”;", "C": "“O acidente com a carreta numa estrada de Minas causou a morte de cerca de 10 pessoas e parece ter sido causado por imperícia do motorista”;", "D": "“Após dois adiamentos e um repasse de R$ 25 bilhões do caixa do BNDES, a Petrobrás anunciou que investirá US$ 174 bi até 2013. O volume é 55% maior do que o registrado no programa anterior”;", "E": "“Um mês antes do Carnaval, a ocupação dos hotéis cariocas já chega a 77%, segundo a Associação Brasileira da Indústria de Hotéis do Rio. Apesar da crise, os números são melhores que os de 2008, quando a taxa de ocupação era de 67% nesse mesmo período”."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',2,'Língua Portuguesa',null,'Entre os diversos tipos de frases há as interrogativas e, entre essas, há aquelas que são chamadas de interrogações retóricas; a pergunta retórica abaixo cuja resposta está contida na pergunta é:','{"A": "Você pode fechar a janela, por favor?", "B": "Esse político está falando a verdade?", "C": "O senhor poderia falar mais alto?", "D": "Eu já não tinha dito isso?", "E": "Quem nunca sentiu medo?"}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',3,'Língua Portuguesa',null,'Abaixo estão frases retiradas de jornais diversos; de cada uma dessas frases foi indicada uma inferência. A frase em que a inferência é adequada é:','{"A": "Em função das chuvas, os rios amazonenses inundaram suas margens / A pesca nos rios amazonenses vai ser mais farta;", "B": "O time do Flamengo comprou mais um jogador / O Flamengo vai ganhar o campeonato brasileiro;", "C": "As férias escolares acabam no próximo domingo, no Rio / O trânsito vai começar a ficar mais difícil no Rio;", "D": "Para treinamento, escoteiros dirigiram o trânsito no centro de Belo Horizonte / Os policiais estão em greve;", "E": "O Carnaval este ano foi menos violento / Poucos turistas vieram para o Carnaval."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',4,'Língua Portuguesa',null,'Uma das formas mais simples de argumentar consiste de duas frases, uma das quais é a conclusão da outra, chamada premissa. A opção abaixo em que a ordem das frases é a de conclusão (C) seguida da premissa (P) é:','{"A": "O leite está transbordando da leiteira / O leite deve ter fervido;", "B": "É possível que Pedro seja eleito senador / Pedro tem muitos eleitores no interior do Estado;", "C": "Meu primo está bem empregado / Meu primo acaba de comprar um carro luxuoso;", "D": "A guerra Rússia x Ucrânia registrou novos combates ontem / A Rússia deve estar enfrentando dificuldades econômicas;", "E": "Minha mulher nunca sofreu um acidente com o carro / Minha mulher é boa motorista."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',5,'Língua Portuguesa',null,'Sempre que, num raciocínio, passamos de uma premissa a uma conclusão (ou vice-versa), assumimos como verdadeira uma ideia intermediária. Essa ideia intermediária está corretamente indicada na seguinte opção:','{"A": "A esposa foi vista pelo irmão dele no cinema, com outro; ele vai separar-se / O irmão dele diz a verdade;", "B": "As pesquisas eleitorais indicam a vitória de Putin; os russos estão perdidos / As pesquisas mostram interesses políticos;", "C": "É conveniente estacionar o carro; há um barulho na traseira / Foram comprados pneus recauchutados;", "D": "Fiz o exercício e encontrei a mesma resposta do professor; acertei mais esse / O professor nem sempre acerta;", "E": "Meu celular despertou; tenho que levantar rápido / Meu gerente é muito exigente quanto a horário."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',6,'Língua Portuguesa',null,'Em algumas frases, os seus autores jogaram com o significado polissêmico de palavras; a opção em que essa estratégia foi empregada é:','{"A": "Os espelhos fariam muito bem em refletir um pouco antes de mostrar as imagens;", "B": "Saudade é a presença da ausência;", "C": "Originalidade não consiste apenas em fazer as coisas de forma diferente, mas também em fazê-las melhor;", "D": "Há três maneiras de fazer as coisas: a maneira errada, a maneira certa e uma maneira melhor;", "E": "Eu quase nada sei, mas desconfio de muita coisa."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',7,'Língua Portuguesa',null,'Observe agora o raciocínio a seguir. 1. Uma pesquisa mostra que os camelôs vendem mais barato; 2. A presença de camelôs na rua é conveniente. Esse raciocínio pode ser refutado porque:','{"A": "a premissa não é geralmente verdadeira;", "B": "a conclusão nada tem a ver com a premissa;", "C": "a conclusão deixa de considerar outros fatores;", "D": "a premissa se apoia em dados falsos;", "E": "a premissa e a conclusão não mostram relação lógica. Tipo 1 – Branca – Página 4"}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',8,'Língua Portuguesa',null,'Considerando que as premissas de um raciocínio podem ser fatos, julgamentos, testemunhos de autoridade ou exemplos, a opção em que a premissa deve ser classificada como julgamento é:','{"A": "Como o estudo da Prefeitura comprovou o perigo de morar nessa encosta, devemos fazer a transferência dos moradores;", "B": "Como o Ibope mostrou a vitória do candidato X, é perda de tempo votar em Y;", "C": "Muitos acidentes ocorrem nesse cruzamento, por isso é urgente o conserto do sinal de trânsito;", "D": "É mais interessante fazer turismo no Nordeste que na Europa, pois devemos ser mais patriotas em nossos gastos;", "E": "Pedro não se deu bem na prova do concurso, por isso devemos estudar muito mais."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',9,'Língua Portuguesa',null,'Abaixo estão frases com raciocínios indutivos; a opção em que a conclusão apontada é fruto de uma generalização é:','{"A": "O computador do TSE tem alta capacidade de contabilização, por isso deve encerrar as eleições em pouco tempo;", "B": "O livro sobre citações de autores célebres é grosso e bem encadernado, além de caro, por isso não deve vender muito;", "C": "Um cachorro salvou a vida de seu dono, avisando-o sobre o risco de desabamento da casa; vou providenciar a adoção de um cachorro para cá;", "D": "Na escola de meu filho mediram a altura de meninos e meninas e chegaram à conclusão de que as mulheres estão crescendo mais do que os homens;", "E": "Os táxis passaram a adotar a política dos supermercados, ou seja, oferecendo preços mais baratos e aumentando o número de clientes, o que se mostrou uma política de sucesso."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',10,'Língua Portuguesa',null,'A frase abaixo que mostra um raciocínio falso, classificado como círculo vicioso, é:','{"A": "Ayrton Senna foi, sem dúvida, o melhor corredor brasileiro de todos os tempos, pois nenhum outro conseguiu igualar-se a ele;", "B": "Todos os nossos problemas desapareceriam se aumentássemos o tamanho da casa onde moramos;", "C": "Não é conveniente para a Prefeitura cancelar esse próximo feriado, pois os cariocas gostam muito de praia;", "D": "Não acredito que você esteja lembrando-me esses fatos; a mim, que sou historiador;", "E": "Estatísticas mostram que mais de 80% dos eleitores preferem votar em pessoas mais velhas, o que favorece os idosos nas próximas eleições."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',11,'Língua Portuguesa',null,'Entre os raciocínios abaixo, aquele que mostra uma falha por apoiar-se numa falsa analogia, é:','{"A": "Os médicos são profissionais diferentes, pois parecem não preocupar-se demais com os seus ganhos;", "B": "O novo atacante do Grêmio deve ser ótimo jogador, pois seu pai chegou a jogar na seleção;", "C": "Os franceses são delicados cozinheiros e os alemães, disciplinados guerreiros, por isso não se entendem;", "D": "A melhor universidade do país é a USP, pois é a que apresenta melhores condições de ensino;", "E": "Se quisermos melhorar o aprendizado da Matemática, basta adotarem-se livros importados."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',12,'Língua Portuguesa',null,'Numa delegacia, uma mulher foi queixar-se do marido, que havia ido embora de casa. No depoimento, fez uma série de frases com vocábulos de conteúdo semântico negativo para trazer mais condenação ao marido. A frase abaixo em que o termo sublinhado NÃO tem conotação negativa é:','{"A": "Meu marido me abandonou na última sexta-feira;", "B": "Ele rabiscou algumas explicações;", "C": "As explicações foram dadas numa folha de papel;", "D": "Ele lambuzou o verso da folha e grudou-a na mesa;", "E": "Foi embora e largou até a porta aberta."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',13,'Língua Portuguesa',null,'Na escrita, ocorrem alguns processos de manipulação da realidade, como a reificação (tratamento de coisa dado ao homem) e a personalização, que dá características humanas a coisas ou animais. A opção abaixo que exemplifica uma personalização é:','{"A": "Seus sonhos se transformaram em pó;", "B": "O mar de Copacabana já matou muitas crianças;", "C": "A morte sai mais barata que a vida;", "D": "Os imigrantes foram depositados num galpão;", "E": "Os prisioneiros vieram empilhados num trem de carga."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',14,'Língua Portuguesa',null,'Em todas as opções abaixo há uma frase que foi reescrita de modo a destacar-se um dos seus elementos; a opção em que essa reescritura foi feita de forma gramaticalmente inadequada, é:','{"A": "Eu trouxe a encomenda para meu irmão / A encomenda, eu lhe dei a meu irmão;", "B": "O gerente entregou a chave ao porteiro / Ao porteiro, o gerente lhe entregou a chave;", "C": "O jogador xingou a torcida ao sair de campo / Ao sair de campo, o jogador xingou a torcida;", "D": "Nunca mais vi meu pai / Ver meu pai, nunca mais;", "E": "Observei a camisa na vitrine / A camisa, eu a observei na vitrine."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',15,'Língua Portuguesa',null,'Observe a seguir o início de um texto. “’Há muita gente complicando a vida do prefeito, inclusive o próprio prefeito’, costuma dizer um vereador. Trata-se de uma revelação de caráter generalizado na Câmara.” A introdução desse texto deve ser identificada como:','{"A": "alusão histórica;", "B": "interrogação;", "C": "suspense;", "D": "convite;", "E": "citação. Tipo 1 – Branca – Página 5 Legislação Específica"}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',16,'Direito Administrativo',null,'Joana, servidora estável ocupante de cargo de provimento efetivo em uma estrutura de poder do Estado do Tocantins, sofreu limitação em sua capacidade mental, devidamente comprovada, no período em que estava em exercício funcional, o que a impossibilitou de exercer as funções afetas ao cargo para o qual fora aprovada em concurso público. Nesse caso, à luz da normatização vigente, Joana deve ser:','{"A": "imediatamente readaptada, sendo investida em cargo de atribuições e responsabilidades compatíveis com sua limitação;", "B": "aposentada por invalidez, ainda que esteja apta a exercer as funções afetas a cargo de atribuições e responsabilidades compatíveis com sua limitação;", "C": "aproveitada em funções compatíveis com as limitações que tenha sofrido em sua capacidade mental, remanejada no subsequente e, passado mais um ano, readaptada;", "D": "remanejada em funções compatíveis com as limitações que tenha sofrido em sua capacidade mental, podendo ser readaptada após dois anos, observados os requisitos legais;", "E": "imediatamente readaptada, sendo investida em cargo de atribuições e responsabilidades compatíveis com sua limitação e, ato contínuo, aproveitada para funções diversas."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',17,'Direito Administrativo',null,'A autarquia Alfa, vinculada a ente federativo submetido à atuação do Tribunal de Contas do Estado do Tocantins, veio a ser extinta em razão da reconhecida ineficiência dos resultados que vinha alcançando. Nesse caso, esse ente da administração pública indireta:','{"A": "não está sujeito à fiscalização do Tribunal de Contas;", "B": "está sujeito à fiscalização do Tribunal de Contas e deve ser apresentada a prestação de contas extraordinária, por ocasião de sua extinção;", "C": "está sujeito à fiscalização do Tribunal de Contas e as respectivas contas devem ser anexadas às contas anuais do ente federativo a que estava vinculado;", "D": "não está sujeito à fiscalização do Tribunal de Contas, mas sua extinção pode gerar reflexos no ente federativo ao qual está vinculado, o que exige a tomada de contas especial;", "E": "somente estará sujeito à fiscalização do Tribunal de Contas, em sede de prestação de contas regular, caso tenha recebido aportes do Tesouro no exercício financeiro de sua extinção."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',18,'Direito Administrativo',null,'Em razão do cargo que ocupa em determinado ente federativo, o qual está submetido à atuação do Tribunal de Contas do Estado do Tocantins, João recebeu determinado numerário para a realização de despesas, de pequeno valor, que não podiam se submeter ao processo ordinário ou comum. Nesse caso, João deve prestar contas:','{"A": "ao Tribunal de Contas, o que ocorrerá a partir de formulário específico, fornecido pelo órgão de controle interno, ao qual serão anexados os documentos comprobatórios das despesas realizadas;", "B": "à autoridade que lhe seja superior, cabendo aos órgãos de controle interno encaminhá-las ao Tribunal de Contas, mensalmente, juntamente com as demais prestações de natureza similar;", "C": "à autoridade que lhe seja superior, cabendo aos órgãos de controle interno encaminhá-las ao Tribunal de Contas, anualmente, juntamente com as demais prestações de natureza similar;", "D": "à autoridade que lhe seja superior, sendo que os órgãos de controle interno submeterão ao Tribunal de Contas apenas aquelas que contiverem irregularidades insanáveis pela própria administração;", "E": "ao Tribunal de Contas, observados os prazos a serem respeitados pelos demais ordenadores de despesas, com a peculiaridade de que as contas serão simplificadas, desacompanhadas de documentos."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',19,'Direito Administrativo',null,'Maria, servidora do Tribunal de Contas do Estado do Tocantins, foi informada por um colega de setor que vinha sendo cogitada a sua designação para atuar na Comissão de Ética. A notícia deixou Maria surpresa, pois, apesar de atuar há uma década no Tribunal, era ocupante de cargo em comissão. Além disso, estava respondendo a um processo disciplinar por ter atuado em processo administrativo de interesse do seu irmão. À luz dessa narrativa, Maria:','{"A": "pode ser designada, em razão da isonomia entre todos os servidores e do princípio da presunção de inocência;", "B": "pode ser designada, pois apenas é exigido que o servidor tenha mais de três anos de carreira e que não tenha sido condenado em processo disciplinar;", "C": "não pode ser designada, mas apenas por ser ocupante de cargo em comissão, não por estar respondendo a processo disciplinar, isto em razão da presunção de inocência;", "D": "não pode ser designada, por ser ocupante de cargo em comissão, acrescendo-se que o fato de estar respondendo a processo disciplinar obstaria o exercício das funções;", "E": "não pode ser designada, mas apenas por estar respondendo a processo disciplinar, não por ser ocupante de cargo em comissão, pois não há distinções entre os servidores. Tipo 1 – Branca – Página 6"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',20,'Direito Administrativo',null,'Joana tomou posse no cargo de auditor de controle externo do Tribunal de Contas do Estado do Tocantins. Durante o seu desenvolvimento funcional, (1) passou para o padrão de vencimento imediatamente superior, isto dentro da mesma classe, observado o interstício mínimo previsto em lei, (2) continuou passando para os padrões subsequentes, dentro da mesma classe, até alcançar o último padrão; e (3) após o interstício de dois anos de efetivo exercício no último padrão da classe, passou para o primeiro padrão da classe imediatamente superior. À luz da narrativa, as situações 1, 2 e 3 descrevem, respectivamente:','{"A": "promoção, progressão e transposição;", "B": "promoção, promoção e transposição;", "C": "progressão, progressão e promoção;", "D": "progressão, avanço e promoção;", "E": "avanço, avanço e progressão. Controle Externo"}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',21,'Direito Administrativo',null,'Maria, após cumprir os requisitos exigidos, teve deferida a sua aposentadoria voluntária por tempo de serviço, sendo o respectivo expediente encaminhado ao Tribunal de Contas do Estado Alfa para fins de registro. Os autos ingressaram no Tribunal em dezembro de 2015 e somente no último mês foi designada a sessão de julgamento na qual seria apreciada a legalidade do ato. À luz da sistemática constitucional, é correto afirmar que:','{"A": "por se tratar de ato de concessão inicial de aposentadoria, não é necessário que Maria seja ouvida, tendo o Tribunal a possibilidade de realizar ampla cognição sobre o ato;", "B": "em razão dos princípios da segurança jurídica e da confiança legítima, o ato de aposentadoria deve ser considerado definitivamente registrado;", "C": "em razão do decurso do tempo, a cognição do ato de aposentadoria pelo Tribunal somente será possível caso haja impugnação de terceiros;", "D": "o Tribunal somente poderá alterar o título de aposentadoria se o respectivo ato contiver vício insanável, não convalidável pelo decurso do tempo;", "E": "embora se trate de ato de concessão inicial de aposentadoria, deve ser assegurado o contraditório e a ampla defesa a Maria."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',22,'Direito Administrativo',null,'O Tribunal de Contas do Estado Beta recebeu, para análise, as contas de governo do prefeito do Município Alfa. Considerando os balizamentos estabelecidos pela Constituição da República de 1988, a referida análise deve:','{"A": "realizar amplo juízo valorativo a respeito das contas, podendo aplicar multa e imputar os débitos que sejam identificados, sem prejuízo do julgamento político a cargo da Câmara Municipal de Alfa, que só rejeitará o parecer por maioria qualificada;", "B": "se restringir à emissão de parecer prévio, que só deixará de prevalecer por maioria qualificada de votos da Câmara Municipal de Alfa, sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo;", "C": "se restringir à emissão de parecer prévio, que só deixará de prevalecer por maioria qualificada de votos da Câmara Municipal de Alfa, não sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo;", "D": "julgar as contas, realizando amplo juízo valorativo a respeito das informações apresentadas, sendo que a sua decisão somente deixará de prevalecer pelo voto de dois terços dos membros da Câmara Municipal de Alfa;", "E": "se restringir à emissão de parecer prévio, que só deixará de prevalecer pela unanimidade dos votos da Câmara Municipal de Alfa, sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',23,'Direito Administrativo',null,'João, servidor público ocupante de cargo de provimento efetivo, que atuara como ordenador de despesas no Município Alfa, foi condenado em processo administrativo, no âmbito do Tribunal de Contas do Estado do Tocantins, pela prática de infração considerada grave. Nesse caso, João:','{"A": "somente pode ser condenado à sanção de multa, além de ter a obrigação de ressarcir os danos que tenha causado ao erário;", "B": "deve ser sempre condenado à sanção de multa, além de ser considerado em débito, se for o caso, ficando ainda inabilitado, nos termos da lei, para o exercício de cargo em comissão ou função de confiança;", "C": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inabilitado, por decisão tomada por maioria absoluta, nos termos da lei, para exercer cargo em comissão ou função de confiança;", "D": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inelegível, por decisão tomada por maioria absoluta, nos termos da lei, para exercer cargo eletivo estadual;", "E": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inelegível, por decisão tomada por maioria de dois terços, nos termos da lei, para exercer qualquer cargo eletivo. Tipo 1 – Branca – Página 7"}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',24,'Direito Administrativo',null,'João, recém-empossado como servidor do Tribunal de Justiça do Estado Alfa, decidiu se inteirar a respeito das linhas de defesa a que estarão sujeitas as contratações públicas, conforme dispõe a Lei nº 14.133/2021. Ao final, concluiu que o controle interno integra a segunda linha de defesa e o Tribunal de Contas figura, isolado, na terceira linha de defesa. À luz do que dispõe o referido diploma normativo, é correto afirmar que a conclusão de João está:','{"A": "errada, pois as linhas de defesa não se apresentam de modo sequencial, mas simultâneo, congregando todos os agentes públicos, as unidades de assessoramento jurídico, o controle interno, o Tribunal de Contas e o Poder Judiciário;", "B": "certa, pois a generalidade dos órgãos de controle interno integra a segunda linha, enquanto o Tribunal de Contas ocupa a última linha de defesa administrativa, imediatamente anterior ao controle jurisdicional;", "C": "certa, ressaltando-se que a última linha de defesa é móvel, de modo que o Tribunal de Contas ali se encontra, de forma isolada, enquanto a questão não é judicializada;", "D": "errada, pois o Tribunal de Contas não integra, isolado, a terceira linha de defesa, estando acompanhado do órgão central de controle interno da Administração;", "E": "errada, pois a generalidade dos órgãos de controle interno não integra a segunda linha, mas, sim, a terceira linha, juntamente com o Tribunal de Contas."}'::jsonb,'D',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',25,'Direito Administrativo',null,'Em determinado contrato administrativo, foi constatado, pelo órgão de controle interno do Município Alfa, a ocorrência de irregularidade insanável no procedimento licitatório que lhe deu origem. Nesse caso, à luz da sistemática estabelecida na Lei nº 14.133/2021, a declaração de nulidade do contrato administrativo:','{"A": "é medida que se opera imediatamente, de pleno direito, apresentando contornos meramente declaratórios, não constitutivos;", "B": "afasta, em qualquer caso, o dever de a Administração indenizar o contratado pelo que houver executado até a data em que for declarada;", "C": "independe de qualquer avaliação complementar pela autoridade administrativa, devendo ser declarada nos cinco dias subsequentes ao conhecimento dos fatos;", "D": "pode vir a produzir efeitos apenas no futuro, observados os limites temporais estabelecidos em lei, para fins de nova contratação, de modo a assegurar a continuidade da atividade administrativa;", "E": "não exige a avaliação dos aspectos circunstanciais e das consequências do ato, o que será feito apenas para fins de dimensionamento da indenização do contratado, que não pode ter concorrido para a nulidade. CONHECIMENTOS ESPECÍFICOS"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',26,'Direito Administrativo',null,'João, prefeito do Município Beta, logo após ser reeleito para o segundo mandato consecutivo à frente do Poder Executivo desse ente federativo, se reuniu com sua equipe com o objetivo de traçar a estratégia a ser adotada para a eleição subsequente. Afinal, o seu crescente prestígio lhe dava esperança de continuar a exercer a representatividade popular. Ao consultar os seus assessores a respeito da possibilidade de ser eleito para um novo mandato, foi-lhe corretamente respondido que a ordem constitucional somente permite:','{"A": "duas reeleições para a chefia do Poder Executivo, logo, João poderia concorrer ao cargo de prefeito do Município Beta na próxima eleição;", "B": "uma reeleição para a chefia do Poder Executivo, de modo que João não poderia concorrer a nenhum cargo eletivo dessa natureza, qualquer que fosse o ente e o nível federativo;", "C": "uma reeleição para cargo, da mesma natureza, de chefe do Poder Executivo, de modo que João apenas não poderia concorrer, na próxima eleição, ao cargo de prefeito municipal, ainda que em Município diverso;", "D": "uma reeleição, no mesmo Município, para a chefia do Poder Executivo, mas João pode concorrer ao cargo de prefeito municipal em Município diverso;", "E": "uma reeleição para a chefia do Poder Executivo, estando o respectivo agente inelegível para qualquer cargo eletivo na eleição subsequente."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',27,'Direito Administrativo',null,'O governador do Estado Alfa foi cientificado de que o Município Beta, situado em seu território, não pagava, há três anos, a dívida decorrente de contratos de financiamento com instituições financeiras governamentais, que tinham por objetivo viabilizar a realização de obras públicas. A ausência de pagamento não decorria de força maior, mas, sim, de opção política do prefeito municipal. Considerando a narrativa, essa espécie de dívida é considerada:','{"A": "flutuante e pode ensejar a decretação da intervenção espontânea;", "B": "fundada e pode ensejar a decretação da intervenção espontânea;", "C": "fundada e somente pode ensejar a decretação da intervenção provocada;", "D": "flutuante e somente pode ensejar a decretação da intervenção provocada;", "E": "mobiliária e somente pode ensejar a decretação da intervenção provocada. Tipo 1 – Branca – Página 8"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',28,'Direito Administrativo',null,'Maria, procuradora-chefe do Município Alfa, foi consultada no corrente mês, pelo prefeito municipal, a respeito dos requisitos de ordem formal a serem observados caso se decidisse pela instituição de um regime próprio de previdência social em âmbito municipal. Maria respondeu, corretamente, que:','{"A": "é vedada a instituição de regime dessa natureza;", "B": "regime dessa natureza pode ser instituído por lei ordinária municipal, observada a simetria com o regime geral de previdência social;", "C": "regime dessa natureza só pode ser instituído pela lei orgânica municipal, observados os balizamentos estabelecidos em lei complementar nacional;", "D": "regime dessa natureza pode ser instituído por lei ordinária municipal, observados os balizamentos estabelecidos em lei complementar nacional;", "E": "regime dessa natureza só pode ser instituído por lei complementar municipal, observados os balizamentos estabelecidos em lei ordinária nacional."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',29,'Direito Administrativo',null,'Após um acordo entre as lideranças partidárias, 27 senadores requereram a criação de uma comissão parlamentar de inquérito (CPI) com o objetivo de apurar notícias de que determinados ilícitos estavam sendo praticados no âmbito de uma autarquia federal. Alguns dos subscritores do requerimento almejavam que a CPI, uma vez instalada, determinasse (1) a interceptação telefônica dos suspeitos da prática de ilícitos e (2) a quebra do seu sigilo bancário. À luz da sistemática constitucional, é correto afirmar que o número de assinaturas:','{"A": "impõe a criação da CPI, cuja instalação não pode ser obstada pela maioria parlamentar ou por órgão diretivo do Senado, sendo que apenas a medida alvitrada em 1 poderia ser adotada;", "B": "impõe a criação da CPI, cuja instalação não pode ser obstada pela maioria parlamentar ou por órgão diretivo do Senado, sendo que apenas a medida alvitrada em 2 poderia ser adotada;", "C": "é insuficiente para a criação da CPI, sendo que, caso uma CPI fosse criada e instalada, as medidas alvitradas em 1 e 2 poderiam ser adotadas;", "D": "é insuficiente para a criação da CPI, sendo que, caso uma CPI fosse criada e instalada, apenas a medida alvitrada em 2 poderia ser adotada;", "E": "é suficiente para o conhecimento do requerimento, mas a criação e consequente instalação da CPI dependem de deliberação da maioria, sendo que apenas a medida alvitrada em 2 poderia ser adotada."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',30,'Direito Administrativo',null,'O juízo de direito de primeira instância, em decisão confirmada pelo Tribunal de Justiça do Estado Alfa, proferiu decisão em que foi negada a legitimidade do Tribunal de Contas Estadual para executar as decisões que proferira, aplicando a sanção de multa aos ordenadores de despesa municipais que causaram danos ao erário municipal. À luz da sistemática vigente, esse entendimento se mostra:','{"A": "certo, pois a execução deveria ser promovida pelo Ministério Público de Contas;", "B": "certo, pois a execução deveria ser promovida pela Procuradoria do Estado;", "C": "errado, pois a multa consubstancia medida punitiva, que deve ser recolhida aos cofres do respectivo Tribunal de Contas;", "D": "errado, pois a multa consubstancia medida punitiva, que deve ser recolhida aos cofres do Estado, por iniciativa do Tribunal de Contas;", "E": "certo, pois a execução deveria ser promovida pela Procuradoria do Município a que está vinculado o respectivo ordenador."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',31,'Direito Constitucional',null,'O prefeito do Município Alfa consultou sua assessoria a respeito da possibilidade de ser majorado o valor venal dos imóveis, via decreto, sem a prévia aprovação de lei que autorizasse essa prática. A consulta do prefeito estava diretamente relacionada à conhecida defasagem do valor venal, o que vinha diminuindo a arrecadação do imposto sobre a propriedade predial e territorial urbana, e à forte mobilização da oposição no âmbito da Câmara Municipal, impedindo a aprovação de uma lei com esse objetivo. A assessoria respondeu, corretamente, que:','{"A": "a majoração do valor venal do imóvel, por estar dissociada do fato gerador do referido imposto, pode ser realizada via decreto;", "B": "qualquer majoração do valor venal do imóvel, ainda que adstrita à correção pelo índice inflacionário anual, exige lei em sentido formal;", "C": "a majoração do valor venal do imóvel, caso se mantenha adstrita à correção pelo índice inflacionário anual, independe de lei em sentido formal;", "D": "na ponderação entre os princípios envolvidos, deve preponderar o interesse público na arrecadação, o que autoriza a majoração do valor venal via decreto;", "E": "está ínsita na competência tributária a adoção dos meios necessários à sua efetivação, de modo que a majoração do valor do imposto, via decreto, decorre da sua criação. Tipo 1 – Branca – Página 9"}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',32,'Direito Constitucional',null,'O Estado Alfa editou norma, por meio de emenda à sua Constituição estadual, estabelecendo que o teto remuneratório dos servidores públicos do Estado e dos Municípios é o subsídio mensal dos desembargadores do Tribunal de Justiça. De acordo com a jurisprudência do Supremo Tribunal Federal, a citada norma:','{"A": "é inconstitucional, pois o teto aplicável aos servidores municipais é, em regra, o subsídio do prefeito;", "B": "é constitucional, pois se trata da aplicação do subteto facultativo único para todos os poderes do Estado e dos correlatos Municípios;", "C": "deve ser objeto de interpretação conforme a Constituição da República de 1988, de maneira que o mencionado teto remuneratório não se aplique aos subsídios dos membros dos poderes;", "D": "deve ser objeto de interpretação conforme a Constituição da República de 1988, de maneira que o mencionado teto remuneratório seja limitado a 95% do subsídio mensal dos ministros do Supremo Tribunal Federal;", "E": "é materialmente constitucional, por tratar do tema nos limites autorizados pela Constituição da República de 1988, mas formalmente inconstitucional, pois, em relação aos Municípios, seria necessária emenda às respectivas leis orgânicas."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',33,'Direito Constitucional',null,'O Município Gama deseja realizar a aquisição de imóvel, cujas características de instalações e de localização tornam necessária sua escolha. Assim sendo, o Município instaurou processo administrativo, no bojo do qual foi certificada a inexistência de imóveis públicos vagos e disponíveis que atendam ao objeto e foram apresentadas as justificativas que demonstram a singularidade do imóvel a ser comprado pela Administração e que evidenciam vantagem para ela. No caso em tela, de acordo com a nova Lei de Licitações e Contratos (Lei nº 14.133/2021), a aquisição ocorrerá mediante:','{"A": "dispensa de licitação, devendo haver prévias avaliação do bem, autorização legislativa e homologação da compra pelo Tribunal de Contas do Estado;", "B": "dispensa de licitação, devendo haver prévias avaliação do bem e autorização legislativa, assim como demonstração de que o valor a ser gasto está compatível com o valor de mercado;", "C": "dispensa de licitação, devendo haver prévias avaliação do bem e autorização do Tribunal de Contas do Estado, assim como demonstração de que o valor a ser gasto está compatível com o valor de mercado;", "D": "inexigibilidade de licitação, devendo haver prévias avaliação do bem e autorização legislativa, assim como demonstração de que o valor a ser gasto está compatível com o valor de mercado;", "E": "inexigibilidade de licitação, devendo haver avaliação prévia do bem, do seu estado de conservação, dos custos de adaptações, quando imprescindíveis às necessidades de utilização, e do prazo de amortização dos investimentos."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',34,'Direito Constitucional',null,'O Tribunal de Contas do Estado Beta aplicou ao prefeito João, do Município Alfa, multa em razão de danos causados ao erário municipal. A decisão do Tribunal de Contas já transitou em julgado, mas João não pagou a multa. Consoante atual jurisprudência do Supremo Tribunal Federal, no caso em tela, quem tem legitimidade para executar o crédito decorrente da multa aplicada a João é o:','{"A": "Estado Beta.", "B": "Município Alfa;", "C": "Tribunal de Contas do Estado Beta, por meio de sua Procuradoria-Geral;", "D": "Tribunal de Contas do Estado Beta, por meio do Ministério Público de Contas;", "E": "Tribunal de Contas do Estado Beta, por meio do conselheiro relator do processo de onde se originou a aplicação da multa."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',35,'Direito Constitucional',null,'José, prefeito do Município Delta, de forma dolosa, praticou ação que ensejou, efetiva e comprovadamente, perda patrimonial do Município, na medida em que, consciente e voluntariamente, realizou operação financeira sem observância das normas legais, causando dano ao erário. Consoante dispõe a Lei de Improbidade Administrativa, com redação atual dada pela Lei nº 14.230/2021, em tese, José:','{"A": "não praticou ato de improbidade administrativa, por falta de adequação típica, mas é passível de responsabilização pelo Tribunal de Contas estadual;", "B": "não praticou ato de improbidade administrativa, por revogação do tipo anterior que considerava a conduta praticada como ato ímprobo, mas pode lhe ser imputado crime de responsabilidade;", "C": "praticou ato de improbidade administrativa e é inviável qualquer tipo de transação, diante da indisponibilidade do direito sancionador, de maneira que José está sujeito, entre outras sanções, à perda da função pública e suspensão dos direitos políticos;", "D": "praticou ato de improbidade administrativa e, caso preenchidos os requisitos legais, é possível a celebração de termo de ajustamento de conduta com o Tribunal de Contas, ouvido o Ministério Público que se manifestará acerca do valor do dano ao erário, com indicação dos parâmetros utilizados, no prazo de trinta dias;", "E": "praticou ato de improbidade administrativa e, caso preenchidos os requisitos legais, é possível a celebração de acordo de não persecução cível com o Ministério Público, circunstância em que, para fins de apuração do valor do dano a ser ressarcido, deve ser realizada a oitiva do Tribunal de Contas, que se manifestará, com indicação dos parâmetros utilizados, no prazo de noventa dias. Tipo 1 – Branca – Página 10"}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',36,'Direito Constitucional',null,'O Tribunal de Contas do Estado do Tocantins, ao apreciar os processos, decidirá: I. em relação ao julgamento das contas públicas, pela regularidade, regularidade com ressalva, irregularidade, ou no sentido de serem as contas iliquidáveis; II. em relação aos processos de admissão, aposentadorias, reformas e pensões, pelo registro ou não do ato e legalidade ou ilegalidade da despesa; III. no caso de parecer prévio, pela aprovação ou rejeição das contas anuais. De acordo com a Lei Orgânica do Tribunal de Contas do Estado do Tocantins, está correto o que se afirma em:','{"A": "somente II;", "B": "somente III;", "C": "somente I e III;", "D": "somente II e III;", "E": "I, II e III."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',37,'Direito Constitucional',null,'As autoridades públicas devem atuar para aumentar a segurança jurídica na aplicação das normas, inclusive por meio de regulamentos, súmulas administrativas e respostas a consultas. Nesse sentido, a Lei de Introdução às Normas do Direito Brasileiro (Decreto-Lei nº 4.657/1942, com redação dada pela Lei nº 13.655/2018) dispõe que, em qualquer órgão ou Poder, a edição de atos normativos por autoridade administrativa, salvo os de mera organização interna:','{"A": "poderá ser precedida de consulta pública para manifestação de interessados, exclusivamente por meio eletrônico e pelo prazo mínimo de trinta dias, caso haja recomendação do órgão de controle interno;", "B": "deverá ser precedida de consulta pública para manifestação de interessados, caso haja recomendação do órgão de controle externo, sob pena de nulidade do ato normativo, por abuso de poder, na modalidade desvio de competência;", "C": "deverá ser precedida de consulta pública para manifestação de interessados, para o exercício regular e legítimo do poder administrativo disciplinar, que embasa diretamente a edição de atos normativos;", "D": "poderá ser precedida de consulta pública para manifestação de interessados, e a convocação conterá a minuta do ato normativo e fixará o prazo e demais condições da consulta pública, observadas as normas legais e regulamentares específicas, se houver;", "E": "deverá ser precedida de consulta pública para manifestação de interessados, caso haja recomendação do órgão de controle externo, sob pena de nulidade do ato normativo, por abuso de poder, na modalidade desvio de finalidade."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',38,'Direito Constitucional',null,'Lei estadual de iniciativa do governador do Estado criou a nova Secretaria Estadual de Combate a Calamidades Públicas. Contudo, não havia ainda dotação na lei orçamentária anual (LOA) para atender às novas despesas necessárias ao funcionamento do novo órgão estadual ainda dentro daquele ano, sem necessidade de se aguardar a elaboração da LOA do ano seguinte. Diante desse cenário, foi necessária a autorização da abertura de créditos por lei para cumprimento dessa finalidade, com devida indicação dos recursos correspondentes. À luz da Lei nº 4.320/1964, tais créditos cuja abertura foi autorizada classificam-se como:','{"A": "ordinários;", "B": "especiais;", "C": "suplementares;", "D": "extraordinários;", "E": "por antecipação de receita."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',39,'Direito Constitucional',null,'A Procuradoria-Geral e a Secretaria da Fazenda do Estado Beta, após os devidos estudos, chegaram à conclusão de que o custo de cobrança de alguns créditos inscritos em dívida ativa estadual suplantavam bastante o valor dos próprios créditos a serem cobrados. Por isso, encaminharam ao governador a orientação de que houvesse o cancelamento de tais débitos cujo montante fosse inferior ao dos respectivos custos de cobrança. Diante desse cenário, à luz do princípio da eficiência e da Lei de Responsabilidade Fiscal, tal cancelamento:','{"A": "deverá estar acompanhado de medidas de compensação, por meio do aumento de receita, proveniente da elevação de alíquotas, ampliação da base de cálculo, majoração ou criação de tributo ou contribuição;", "B": "deverá estar acompanhado de demonstração de que não afetará as metas de resultados fiscais previstas no anexo próprio da lei de diretrizes orçamentárias;", "C": "deverá estar acompanhado de estimativa do impacto orçamentário-financeiro no exercício em que deva iniciar sua vigência e nos dois seguintes;", "D": "entrará em vigor apenas quando implementadas medidas de compensação;", "E": "não se classifica como renúncia de receita pública para fins da Lei de Responsabilidade Fiscal. Tipo 1 – Branca – Página 11"}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',40,'Direito Financeiro',null,'Em 2022, último ano de mandato do governador do Estado Gama, apurou-se que, no primeiro quadrimestre, a despesa total com pessoal do Poder Executivo estadual alcançou o percentual de 49,5% da receita corrente líquida (RCL). Diante dessa apuração feita ao final do primeiro quadrimestre de 2022 e à luz da Lei de Responsabilidade Fiscal, analise as afirmativas a seguir. I. O Poder Executivo fica impedido de obter garantia, direta ou indireta, de outro ente. II. O Poder Executivo fica impedido de receber transferências obrigatórias. III. Os Poderes do Estado Gama ficam impedidos de alterar a estrutura de carreira dos servidores que implique aumento de despesa. Está correto o que se afirma em:','{"A": "somente I;", "B": "somente II;", "C": "somente III;", "D": "somente II e III;", "E": "I, II e III."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',41,'Direito Financeiro',null,'O presidente da República enviou ao Congresso Nacional o projeto de lei de diretrizes orçamentárias (LDO) para o ano de 2022. No Legislativo, o projeto começou a tramitar na Comissão Mista permanente de Planos, Orçamentos Públicos e Fiscalização (CMO). Enquanto seguiam os trabalhos de exame na CMO, o presidente da República enviou mensagem ao Congresso Nacional para propor alteração em uma parte do projeto da LDO. Diante desse cenário e à luz da Constituição da República de 1988, é correto afirmar que:','{"A": "uma vez encaminhado o projeto de LDO ao Congresso Nacional, o presidente da República não poderá mais enviar mensagem ao Legislativo para propor modificações a esse projeto;", "B": "a CMO é composta por deputados, senadores, membros representantes da sociedade civil escolhidos pelo Congresso Nacional, membros da Secretaria do Tesouro Nacional e membros indicados pelo Tribunal de Contas da União;", "C": "a emissão de parecer da CMO sobre o projeto de LDO, devidamente votado e aprovado no âmbito dessa Comissão Mista, dispensa a votação posterior pelos demais membros da Câmara dos Deputados e do Senado Federal;", "D": "deve integrar o projeto de LDO, para o exercício de 2022 e, pelo menos, para os dois exercícios subsequentes, anexo com previsão de agregados fiscais e a proporção dos recursos para investimentos que serão alocados na lei orçamentária anual para a continuidade daqueles em andamento;", "E": "diferentemente do projeto de lei orçamentária anual, em que podem ser propostas emendas parlamentares ao projeto, não se admite a apresentação na CMO de emendas parlamentares ao projeto de LDO."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',42,'Direito Financeiro',null,'O Município X requereu ao BNDES (instituição financeira federal) a concessão de empréstimo, em regime de juros especiais para os entes municipais, a fim de obter recursos para pagamento de aumento concedido aos servidores municipais ativos. Diante desse cenário e à luz da Constituição da República de 1988, esse empréstimo requerido pelo Município X junto ao BNDES:','{"A": "pode ser realizado, uma vez que será feito em regime de juros especiais para os entes municipais;", "B": "pode ser realizado, uma vez que é permitido junto a instituição financeira vinculada ao governo federal;", "C": "não pode ser realizado, uma vez que é vedado junto a instituição financeira vinculada ao governo federal;", "D": "não pode ser realizado, uma vez que é permitido apenas junto a instituição financeira vinculada ao governo estadual;", "E": "não pode ser realizado, uma vez que é permitido apenas para pagamento de proventos de aposentadoria de servidores inativos e seus respectivos pensionistas."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',43,'Direito Tributário',null,'Analise as situações apresentadas a seguir e, à luz da Lei nº 4.320/1964, classifique as seguintes despesas públicas abaixo relacionadas. I. Pagamento de pensionistas de militares falecidos do Corpo de Bombeiros Estadual; II. Amortização da dívida pública estadual; III. Aquisição de galpão onde já funciona posto do Detran. A classificação correta é, respectivamente:','{"A": "I. Despesa de custeio; II. Transferência corrente; III. Investimento;", "B": "I. Despesa de custeio; II. Transferência de capital; III. Inversão financeira;", "C": "I. Despesa de custeio; II. Transferência de capital; III. Investimento;", "D": "I. Transferência corrente; II. Transferência corrente; III. Investimento;", "E": "I. Transferência corrente; II. Transferência de capital; III. Inversão financeira."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',44,'Direito Tributário',null,'Marcos, proprietário de três imóveis em Palmas/TO e domiciliado nesse Município, resolve em 2021 fazer doação de um dos imóveis a seu único herdeiro, seu filho João, domiciliado em Fortaleza/CE. A doação é devidamente registrada no Registro de Imóveis, mas com subavaliação do bem, resultando em pagamento a menor do Imposto sobre a transmissão causa mortis e doação (ITCMD), o que somente é percebido posteriormente pelo Fisco estadual. Diante desse cenário e à luz do Código Tributário do Estado do Tocantins, é correto afirmar que:','{"A": "João é o contribuinte do ITCMD incidente sobre esta doação;", "B": "Marcos é o contribuinte do ITCMD incidente sobre esta doação;", "C": "o Fisco estadual poderá fazer um lançamento por declaração da parte que não foi recolhida;", "D": "o Fisco estadual poderá fazer um lançamento por homologação da parte que não foi recolhida;", "E": "na impossibilidade de exigência do cumprimento da parcela faltante da obrigação principal pelo contribuinte João, Marcos responderá solidariamente com ele. Tipo 1 – Branca – Página 12"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',45,'Direito Tributário',null,'Maria, domiciliada em Porto Nacional/TO, pagou em cota única, em janeiro de 2021, o Imposto sobre a Propriedade de Veículos Automotores (IPVA) de seu automóvel licenciado e emplacado nesse Município. Não percebera, porém, que não havia pagado o débito de IPVA referente ao ano de 2014. Em 01/06/2021, teve seu automóvel furtado. Dirigiu-se até uma delegacia de polícia para registrar a ocorrência policial, tendo havido também comunicação pelo sistema Renavam ao Detran/TO. Diante desse cenário e à luz do Código Tributário do Estado do Tocantins, é correto afirmar que:','{"A": "o IPVA não poderá ter alíquotas diferenciadas em função do tipo e utilização do automóvel;", "B": "a dívida de IPVA referente ao ano de 2014 foi alcançada pela decadência tributária;", "C": "ao Município de Porto Nacional pertence 75% do produto da arrecadação do IPVA dos automóveis licenciados em seu território;", "D": "cabe pedido de restituição do IPVA pago proporcionalmente, à razão de 1/12 por mês, contado a partir do mês seguinte à data do evento, desde que haja o prévio reconhecimento da isenção pela Secretaria da Fazenda;", "E": "havendo valores a débito e a crédito de IPVA, incidentes sobre um mesmo veículo, a Secretaria da Fazenda somente pode processar a compensação destes se houver expressa solicitação do contribuinte."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',46,'Direito Tributário',null,'A sociedade empresária XYZ Ltda. possuía débitos de taxas estaduais e resolveu aderir a um programa de parcelamento de débitos tributários inscritos em dívida ativa previsto em lei específica do Estado Alfa. Diante desse cenário e à luz do Código Tributário Nacional, é correto afirmar que:','{"A": "o momento da concessão de tal parcelamento é causa de extinção do crédito tributário;", "B": "XYZ Ltda. fará jus a uma certidão positiva com efeitos de negativa durante a pendência de tal parcelamento;", "C": "a dívida ativa regularmente inscrita goza da presunção de certeza e liquidez, mas sem efeito de prova pré-constituída;", "D": "não podem ser aplicadas subsidiariamente ao parcelamento as disposições relativas à moratória previstas no Código Tributário Nacional;", "E": "durante tal parcelamento, fica suspenso o cumprimento das obrigações acessórias dependentes da obrigação principal cujo crédito está sendo parcelado."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',47,'Direito Tributário',null,'Quanto às imunidades constitucionais de tributos relacionados ao prédio-sede do Tribunal de Contas do Estado Beta, de propriedade do mesmo Estado, analise as afirmativas a seguir. I. Há imunidade quanto à contribuição municipal para o custeio dos serviços de iluminação pública incidente sobre o consumo de energia deste prédio-sede de Tribunal de Contas Estadual. II. Não há imunidade quanto à taxa municipal de coleta de lixo domiciliar proveniente deste prédio-sede de Tribunal de Contas Estadual. III. Há imunidade quanto à contribuição de melhoria municipal instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária deste prédio-sede de Tribunal de Contas Estadual. Está correto o que se afirma em:','{"A": "somente I;", "B": "somente II;", "C": "somente III;", "D": "somente I e III;", "E": "I, II e III."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',48,'Direito Tributário',null,'O presidente da República, por meio de decreto publicado no Diário Oficial da União em janeiro de 2022, visando a estimular o consumo, reduziu para zero a alíquota do Imposto sobre Produtos Industrializados (IPI) referente a certos produtos eletrodomésticos, a contar da data de sua publicação. Diante desse cenário, o referido decreto:','{"A": "não poderia reduzir a zero tal alíquota;", "B": "violou o princípio da legalidade tributária;", "C": "poderia elevar a alíquota do IPI, mas não reduzi-la;", "D": "não violou o princípio da anterioridade tributária nonagesimal;", "E": "violou o princípio da anterioridade tributária do exercício financeiro seguinte."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',49,'Direito Civil',null,'Zelinda e Cláudio compareceram ao cartório para celebrar contrato de compra e venda de imóvel, tendo declarado, para fins de lavratura da escritura pública, que o preço pago por Zelinda seria de R$ 1.200.000,00 em troca da transferência da propriedade do apartamento de Cláudio. Entretanto, o que seria efetivamente pago, conforme avençado entre os dois, era o valor de R$ 2.000.000,00, que foi o montante efetivamente recebido por Cláudio de Zelinda: o acordo entre as partes para a declaração de valor menor tinha por objetivo pagar menos impostos. Nesse caso, ocorreu:','{"A": "fraude contra credores;", "B": "dolo;", "C": "lesão;", "D": "simulação;", "E": "estado de perigo. Tipo 1 – Branca – Página 13"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',50,'Direito Empresarial',null,'Fabiano, portador de nota promissória vencida há três meses, e sem receber o devido pagamento, realizou, junto ao tabelionato competente, o protesto desse título de crédito. Diante disso, o protesto cambial:','{"A": "interrompe o prazo prescricional;", "B": "suspende o prazo prescricional;", "C": "impede a fluência do prazo prescricional;", "D": "prorroga o prazo prescricional;", "E": "não influi no prazo prescricional."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',51,'Direito Empresarial',null,'A JPD está sendo cobrada por uma multa contratual de dez mil reais em virtude de não ter cumprido pontualmente sua obrigação de fornecer à LMT determinado maquinário. A cobrança é objeto de litígio judicial, pois a JPD alega que a multa é excessiva, enquanto a LMT, ao contrário, reputa o valor insuficiente para cobrir seus prejuízos e requer majoração. Sobre o caso, é correto afirmar que:','{"A": "a redução equitativa da multa pode ser realizada de ofício pelo juiz, se reputá-la manifestamente excessiva, tendo em vista a natureza e a finalidade da obrigação;", "B": "não será possível a redução judicial da multa se houver cláusula expressa afastando essa possibilidade, tendo em vista se tratar de contrato paritário;", "C": "caso comprovado que a multa não é suficiente para cobrir o prejuízo da LMT, será cabível indenização suplementar, salvo cláusula em sentido contrário;", "D": "o juiz poderá reduzir a multa a zero, afastando sua cominação, se o credor não for capaz de provar ter sofrido qualquer prejuízo em decorrência do inadimplemento;", "E": "o valor da multa somente poderá ser reduzido em caso de cumprimento parcial da obrigação que ela garante."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',52,'Direito Empresarial',null,'Quando a Gama S/A, firma de contabilidade, decidiu fechar seu escritório no centro de Palmas, optou por vender as três impressoras seminovas que lá se encontravam. A Grafet Ltda. comprou as três, mas constatou problemas após recebê-las. O rolamento interno da impressora X estava desgastado pelo uso, embora isso não chegasse a prejudicar a impressão ou o seu valor. A bandeja externa de papel da impressora Y estava quebrada e não encaixava mais na máquina, tanto que foi recebida em separado. A impressora Z, por sua vez, funcionou bem durante uma semana, mas depois parou: o técnico chamado informou que a causa do defeito foi um cabeçote interno, que deveria ter sido substituído há pelo menos seis meses. Diante disso, a Grafet pode enjeitar, por vício redibitório:','{"A": "a impressora X;", "B": "as impressoras X e Y;", "C": "a impressora Y;", "D": "as impressoras Y e Z;", "E": "a impressora Z."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',53,'Direito Civil',null,'Marcelo adquiriu há mais de três anos uma casa de veraneio no campo. Entretanto, nunca ocupou ou exerceu quaisquer atos de posse sobre o bem. Até o momento, todavia, ninguém mais veio a apossar-se do bem, estando ainda desocupado. Caso a conduta de Marcelo venha a ser considerada abandono do bem, ele poderá ser arrecadado pelo(a):','{"A": "União, caso se trate de imóvel urbano, onde quer que ele se localize;", "B": "Estado, caso se trate de imóvel urbano e se encontre na respectiva circunscrição;", "C": "Município ou Distrito Federal, caso se trate de imóvel urbano e se encontre na respectiva circunscrição;", "D": "Estado, caso se trate de imóvel rural e se encontre na respectiva circunscrição;", "E": "Município ou Distrito Federal, caso se trate de imóvel rural e se encontre na respectiva circunscrição."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',54,'Direito Civil',null,'Astolfo e Maria casaram-se sob o regime da comunhão parcial de bens. Na constância do casamento, Astolfo ganhou um barco em um sorteio no clube e recebeu um sítio de presente de seu pai; Maria recebeu um apartamento por herança de sua mãe e comprou uma casa. Na hipótese de divórcio, serão considerados bens comuns somente:','{"A": "a casa;", "B": "o apartamento;", "C": "o barco e o sítio;", "D": "o barco e a casa;", "E": "o sítio, o apartamento e a casa."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',55,'Direito Penal',null,'No tocante à extinção da punibilidade penal, é correto afirmar que:','{"A": "no crime de peculato culposo, a reparação do dano, se realizada após a sentença irrecorrível, acarreta a extinção da punibilidade;", "B": "nos crimes conexos, a extinção da punibilidade de um deles não impede, quanto aos outros, a agravação da pena resultante da conexão;", "C": "no crime de apropriação indébita previdenciária, extingue-se a punibilidade com o pagamento das contribuições devidas à previdência social, se realizado após o início da ação fiscal;", "D": "nos crimes contra a administração pública, estende-se o perdão judicial aos demais participantes do crime, em razão de se tratar de circunstância pessoal;", "E": "nos crimes contra a ordem tributária, o pagamento integral do tributo, após a sentença condenatória irrecorrível, implica extinção da punibilidade. Tipo 1 – Branca – Página 14"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',56,'Direito Penal',null,'A prefeita Rebeca, juntamente com a secretária municipal Raquel, em perfeita comunhão de ações e desígnios, com vistas a direcionarem determinado procedimento licitatório à empresa de Renato, empresário e parente em comum de ambas, ofereceram vantagem econômica consistente em R$ 50.000,00 à licitante e empresária Sofia para que esta desistisse da licitação. Sofia desistiu em razão de ter aceitado o referido valor, sendo o certame licitatório vencido pela empresa de Renato. Sob o prisma penal, é correto afirmar, em relação às condutas de Rebeca, Raquel e Sofia, que:','{"A": "Rebeca e Raquel cometeram o crime de corrupção ativa, e Sofia, o de corrupção passiva;", "B": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e Sofia, o de corrupção ativa;", "C": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e a conduta de Sofia é penalmente atípica;", "D": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e Sofia, o de corrupção passiva;", "E": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e Sofia incorre nas mesmas penas do crime de afastamento de licitante."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',57,'Direito Penal',null,'Em relação à prescrição como causa de extinção da punibilidade, é correto afirmar que:','{"A": "os prazos prescricionais previstos para as penas privativas de liberdade não se aplicam às penas restritivas de direito;", "B": "o prazo prescricional começa a correr, antes de a sentença transitar em julgado, nos crimes permanentes, do dia em que cessou a permanência;", "C": "os prazos prescricionais se reduzem de 1/3 se o criminoso era, ao tempo do crime, maior de 70 anos;", "D": "o curso do prazo prescricional se interrompe pelo oferecimento da denúncia;", "E": "a prescrição da pena de multa ocorrerá em três anos quando a multa for a única pena cominada ou aplicada."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',58,'Direito Penal',null,'A respeito das normas e princípios que regem a aplicação da lei penal no tempo e no espaço, é correto afirmar que:','{"A": "admite-se sejam as normas penais incriminadoras criadas por lei, medida provisória ou decreto legislativo;", "B": "considera-se praticado o crime no momento de seu resultado, ainda que outro seja o momento da ação ou omissão;", "C": "aplica-se a lei penal incriminadora mais gravosa a fatos anteriores já decididos por sentença condenatória transitada em julgado;", "D": "aplicam-se as regras gerais do Código Penal aos crimes previstos em lei especial, se esta dispuser de maneira diversa;", "E": "aplica-se a lei penal temporária, embora decorrido o período de sua duração, aos fatos praticados durante a sua vigência."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',59,'Direito Penal',null,'Renato, Ricardo e Roberto, policiais civis lotados na Secretaria Municipal de Segurança Pública de determinado Município, associaram-se, entre si, com perfeita divisão de tarefas, para a prática de vários crimes de extorsão, de concussão e de corrupção, utilizando-se, para a prática de alguns delitos, das armas de fogo que possuíam em razão de suas funções. Os três foram presos em flagrante quando do cometimento de um delito de corrupção, para a consecução do qual não se utilizaram das referidas armas de fogo. Além de responderem pelo crime de corrupção, o fato de terem se associado para a prática de crimes corresponde à figura típica de crime de:','{"A": "associação criminosa, com a incidência da majorante relativa ao fato de os agentes serem servidores públicos;", "B": "constituição de milícia privada, não incidindo a majorante do emprego de arma de fogo;", "C": "associação criminosa, com incidência da causa de aumento de pena em razão de a associação ser armada;", "D": "constituir e integrar organização criminosa armada, não incidindo a majorante do emprego de arma de fogo;", "E": "constituir e integrar organização criminosa armada, com incidência da majorante pelo fato de os agentes serem servidores públicos."}'::jsonb,'C',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',60,'Direito Penal',null,'Relativamente às condutas que caracterizam o crime de lavagem de dinheiro previsto na Lei nº 9.613/1998, é correto afirmar que:','{"A": "a infração penal antecedente deve ser crime punido com reclusão e gerar proveito econômico àquele que pratica o crime de lavagem;", "B": "não se punem as formas tentadas das condutas que consubstanciam o crime de lavagem de dinheiro;", "C": "a pena será aumentada de 1/3 a 2/3 se o crime for cometido por intermédio de organização criminosa;", "D": "não se pune a dissimulação de valores provenientes de infração penal quando são convertidos em ativos lícitos;", "E": "extinta a punibilidade da infração penal antecedente, deixa de ser punível o crime de lavagem de dinheiro."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',61,'Administração Financeira e Orçamentária',null,'O modelo orçamentário de referência para o planejamento das entidades públicas brasileiras é o orçamento-programa. A classificação programática da despesa está alinhada a esse modelo. Nesse contexto, um instrumento de programação que envolve um conjunto de operações que se realizam de modo contínuo e permanente e que contribuem para a manutenção da ação de governo, a exemplo de fiscalização e monitoramento da qualidade de combustíveis automotores, deve ser classificado como:','{"A": "aplicação direta;", "B": "atividade;", "C": "projeto;", "D": "operação especial;", "E": "encargo especial. Tipo 1 – Branca – Página 15"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',62,'Administração Financeira e Orçamentária',null,'Um estado da federação recebeu recursos decorrentes de emendas individuais impositivas apresentadas ao projeto de Lei Orçamentária Anual da União, por meio de transferência especial. Os recursos foram da ordem de R$ 800 mil. Pelas regras constitucionais, para aplicação desses recursos:','{"A": "até R$ 200 mil poderão ser aplicados em despesas com ações e serviços públicos de saúde;", "B": "até R$ 200 mil poderão ser aplicados na amortização da dívida consolidada do ente;", "C": "o valor deverá ser igualmente dividido entre despesas e ações nas áreas de saúde e de educação;", "D": "o valor total deverá ser aplicado nas áreas de competência constitucional da União;", "E": "pelo menos R$ 560 mil deverão ser aplicados em despesas de capital."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',63,'Administração Financeira e Orçamentária',null,'Em sentido amplo, os ingressos de recursos financeiros nos cofres do Estado denominam-se receitas públicas, porém nem todas pertencem efetivamente ao ente e são destinadas ao custeio da ação pública. Esse é o caso de receitas:','{"A": "decorrentes de juros de operações de crédito;", "B": "geradas pela alienação de bens do patrimônio público;", "C": "originárias de compensações financeiras;", "D": "que representam apenas entradas compensatórias;", "E": "que resultam da cobrança de dívida ativa."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',64,'Administração Financeira e Orçamentária',null,'Com o intuito de subsidiar a promoção de uma gestão fiscal responsável, a Lei de Responsabilidade Fiscal dispôs sobre a definição de metas e restrições para assegurar o cumprimento dessas metas. A limitação de empenho e movimentação financeira é uma medida que deve ser adotada quando a realização da receita ameaçar o cumprimento das metas de resultado primário ou nominal, e pode incidir sobre despesas:','{"A": "com juros e encargos da dívida;", "B": "com pagamento de pessoal e encargos sociais;", "C": "de transferências intergovernamentais legalmente previstas;", "D": "discricionárias destinadas a ações e serviços públicos de saúde;", "E": "relativas à inovação custeadas por fundo criado para tal finalidade."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',65,'Administração Financeira e Orçamentária',null,'Ao final de um determinado período de apuração, um estado da federação apurou uma Receita Corrente Líquida de R$ 12 bilhões. A partir das disposições da Lei de Responsabilidade Fiscal, o percentual de despesa total com pessoal do tribunal de contas do referido ente:','{"A": "deve se limitar a 2,5% da RCL;", "B": "está limitado a 2% da RCL;", "C": "corresponde a 0,6% da RCL;", "D": "é apurado de forma consolidada com o Poder Executivo;", "E": "é definido juntamente com o do Poder Legislativo."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',66,'Auditoria',null,'As normas de auditoria exigem que o trabalho do auditor seja adequadamente planejado. Um dos objetivos principais do planejamento da auditoria é auxiliar o auditor:','{"A": "quanto a forma e conteúdo de sua opinião no relatório de auditoria das demonstrações contábeis;", "B": "a uma efetiva comunicação com os responsáveis pela governança e identificar alguns assuntos específicos a serem comunicados a eles;", "C": "a avaliar o efeito de distorções identificadas durante a auditoria;", "D": "a avaliar o efeito de distorções não corrigidas nas demonstrações contábeis;", "E": "a conhecer a natureza das operações e dos negócios da organização para definir o alcance, a época e a direção da auditoria."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',67,'Auditoria',null,'A metodologia de avaliação dos controles internos consiste em avaliar os controles internos existentes e quantificá-los em níveis de efetividade. Dessa forma, uma empresa apresentou os seguintes controles internos, avaliados em: 1 (controles não funcionais), 0,5 (controles funcionais medianos) e 0,2 (controles funcionais fortes). Os auditores, ao solicitarem tais documentos de avaliação, podem concluir que:','{"A": "caso existam controles funcionais em uma atividade, a multiplicação do risco residual ao valor do nível dos controles internos resultará em um menor risco inerente;", "B": "independentemente do nível de controles internos, a multiplicação do risco inerente ao valor do nível dos controles internos resultará em um maior risco residual;", "C": "caso existam controles funcionais em uma atividade, a multiplicação do risco inerente ao valor do nível dos controles internos resultará em um menor risco residual;", "D": "independentemente do nível de controles internos, a multiplicação do risco inerente ao valor do nível dos controles internos resultará em um menor risco residual;", "E": "caso existam controles funcionais em uma atividade, a multiplicação da probabilidade e do impacto resultará em um menor risco residual."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',68,'Auditoria',null,'O objetivo do auditor é definir e executar procedimentos de auditoria que permitam a ele conseguir evidência de auditoria apropriada e suficiente que lhe possibilite obter conclusões razoáveis para fundamentar a sua opinião. Nesse sentido, a confiabilidade da evidência de auditoria é influenciada pela fonte, por sua natureza e é mais confiável quando obtida:','{"A": "de fontes independentes externas à entidade e confirmada em documento eletrônico ou em papel;", "B": "por meio da indagação a respeito da aplicação de controle, em vez da observação da aplicação de controle;", "C": "pela representação formal, pois fornece evidência de auditoria apropriada e suficiente;", "D": "pela cópia de um documento fiscal obtida por intermédio de fontes internas da empresa do que diretamente pelo auditor;", "E": "por meio da indagação a respeito da contagem de estoques, em vez da observação do auditor da contagem do estoque pelo pessoal da entidade. Tipo 1 – Branca – Página 16"}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',69,'Auditoria',null,'Uma empresa reapresentou valores em decorrência da adoção de novos pronunciamentos contábeis e o auditor emitiu em seu relatório de auditoria as seguintes informações: “Em nossa opinião, as demonstrações financeiras apresentam adequadamente, em todos os aspectos relevantes, a posição patrimonial e financeira, individual e consolidada, da empresa XYZ em 31 de dezembro de 20XX, o desempenho individual e consolidado de suas operações e os seus respectivos fluxos de caixa individuais e consolidados para o exercício findo nessa data, de acordo com as práticas contábeis adotadas no Brasil e com as normas internacionais de relatório financeiro. Conforme mencionado na nota explicativa X, em decorrência da adoção dos novos pronunciamentos contábeis, os valores correspondentes, individuais e consolidados, relativos aos balanços patrimoniais em 31 de dezembro de 20XX e as respectivas demonstrações do resultado, do resultado abrangente, das mutações do patrimônio líquido, dos fluxos de caixa e do valor adicionado para o exercício findo nessa data, apresentados para fins de comparação, foram ajustados e estão sendo reapresentados”. Dessa forma, o auditor emitiu uma opinião:','{"A": "com ressalva;", "B": "negativa;", "C": "modificada;", "D": "adversa;", "E": "com parágrafo de ênfase."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',70,'Auditoria',null,'Existem diversos tipos de auditoria, contudo, uma delas possui características próprias que a distingue dos outros tipos. Dessa forma, a que apresenta uma variedade e complexidade de questões a serem tratadas, possui maior flexibilidade na escolha de temas, objetos de auditoria, métodos de trabalho e forma de comunicar suas conclusões é a auditoria:','{"A": "de conformidade;", "B": "financeira;", "C": "contábil;", "D": "operacional;", "E": "ambiental. DISCURSIVA 1 João Felipe teve seu registro de candidatura ao cargo de deputado estadual impugnado pela coligação “Justiça Agora!”, com o argumento de que o Tribunal de Contas do Estado do Tocantins, em sessão de outubro de 2021, emitiu parecer pela rejeição de suas contas referentes ao exercício do ano de 2020, quando ocupava o cargo de prefeito do Município de Gurupi/TO. Tendo em vista essa situação, discorra, de forma fundamentada, sobre: a) a natureza jurídica do parecer do Tribunal de Contas, à luz das suas atribuições; b) a natureza jurídica das contas do prefeito; c) a competência para apreciar as contas de prefeito. Valor: 15 pontos Máximo de 15 linhas. 2 Considere que você, como auditor do Tribunal de Contas do Estado Alfa, é integrante do setor responsável pelo controle da regularidade dos pagamentos de precatórios. Diante disso e apenas à luz da Constituição da República de 1988, apresente resumidamente as três ordens cronológicas de preferências no pagamento de precatórios e suas características essenciais, iniciando sua resposta com os créditos de precatórios que possuem maior prioridade até chegar àqueles com menor prioridade (não é necessário expor o trâmite para expedição dos precatórios). Valor: 15 pontos Máximo de 15 linhas. Tipo 1 – Branca – Página 17 RASCUNHO - Prova Discursiva - Questão 1 1 5 10 15 RASCUNHO - Prova Discursiva - Questão 2 1 5 10 15"}'::jsonb,'D',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','alternativa muito longa: pode conter texto de outra questão; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno')
